using System;
using System.Linq;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using FalloutPort;
public static class FitRosterGrips {
 const string Root="Assets/FalloutPort/Weapons/Grips";
 static bool Arm(BoneWeight w,Transform[] bones,bool left){int[] b={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] a={w.weight0,w.weight1,w.weight2,w.weight3};float t=0;for(int i=0;i<4;i++){string n=bones[b[i]].name;if((left||n.EndsWith(".R"))&&(n.Contains("wrist")||n.Contains("finger")||n.Contains("metacarpal")))t+=a[i];}return t>.7f;}
 public static string FitAll(){Directory.CreateDirectory(Root);AssetDatabase.Refresh();var defs=Resources.LoadAll<PortWeaponDefinition>("WeaponDefinitions").OrderBy(x=>x.id);int count=0;foreach(var def in defs){Fit(def);File.WriteAllText("Logs/WeaponGripImport.txt",(++count)+" / 44 "+def.id);}AssetDatabase.SaveAssets();return "Fitted "+count+" weapon grips";}
 public static void Fit(PortWeaponDefinition def){
  var root=PrefabUtility.LoadPrefabContents(AssetDatabase.GetAssetPath(def.prefab));var old=root.transform.Find("First person arms");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);bool left=def.hasLeftGrip&&!def.oneHanded;var armRoot=new GameObject("First person arms");armRoot.layer=2;armRoot.transform.SetParent(root.transform,false);
  var source=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NPCCollection/Prefabs/04_Security.prefab"));source.transform.position=Vector3.zero;var animator=source.GetComponentInChildren<Animator>();animator.runtimeAnimatorController.animationClips.First(x=>x.name.Contains("Idle_Breathe")).SampleAnimation(animator.gameObject,0);animator.enabled=false;var bones=source.GetComponentsInChildren<Transform>();
  foreach(var side in left?new[]{"R","L"}:new[]{"R"}){bool right=side=="R";var upper=bones.First(x=>x.name=="upperarm01."+side);var elbow=bones.First(x=>x.name=="lowerarm01."+side);var wrist=bones.First(x=>x.name=="wrist."+side);var index=bones.First(x=>x.name=="finger2-1."+side);var little=bones.First(x=>x.name=="finger5-1."+side);Vector3 grip=right?def.rightGrip:def.leftGrip;Quaternion rotation=right?def.rightRotation:def.leftRotation;Vector3 forward=rotation*Vector3.forward,back=rotation*Vector3.up,across=rotation*Vector3.right;Vector3 w=grip-forward*.085f+back*.028f,e=new Vector3(right?.28f:-.28f,-.28f,Mathf.Min(grip.z-.15f,-.06f)),u=new Vector3(right?.4f:-.4f,-.48f,-.38f);upper.position=u;upper.rotation=Quaternion.FromToRotation(elbow.position-u,e-u)*upper.rotation;elbow.position=e;elbow.rotation=Quaternion.FromToRotation(wrist.position-e,w-e)*elbow.rotation;wrist.position=w;Quaternion oldFrame=Quaternion.LookRotation((index.position+little.position)*.5f-wrist.position,little.position-index.position);wrist.rotation=Quaternion.LookRotation(forward,across)*Quaternion.Inverse(oldFrame)*wrist.rotation;
   string pose=right?def.rightPose:def.leftPose;if(pose!="trigger"){var a=bones.First(x=>x.name=="finger1-1."+side);var b=bones.First(x=>x.name=="finger1-2."+side);var c=bones.First(x=>x.name=="finger1-3."+side);a.rotation=Quaternion.FromToRotation(b.position-a.position,(across-back*.35f).normalized)*a.rotation;b.rotation=Quaternion.FromToRotation(c.position-b.position,(across*.35f-back).normalized)*b.rotation;}
   for(int digit=2;digit<=5;digit++){var a=bones.First(x=>x.name=="finger"+digit+"-1."+side);var b=bones.First(x=>x.name=="finger"+digit+"-2."+side);var c=bones.First(x=>x.name=="finger"+digit+"-3."+side);a.rotation=Quaternion.FromToRotation(b.position-a.position,-back)*a.rotation;b.rotation=Quaternion.FromToRotation(c.position-b.position,-forward)*b.rotation;c.rotation=Quaternion.AngleAxis(right?-30:30,across)*c.rotation;}
  }
  int number=0;foreach(var r in source.GetComponentsInChildren<SkinnedMeshRenderer>()){if(r.name!="Head_and_hands")continue;var original=r.sharedMesh;var weights=original.boneWeights;var matrices=r.bones.Select((b,i)=>b.localToWorldMatrix*original.bindposes[i]).ToArray();var vs=original.vertices;var normals=original.normals;for(int i=0;i<vs.Length;i++){var w=weights[i];var v=vs[i];var n=normals[i];vs[i]=matrices[w.boneIndex0].MultiplyPoint3x4(v)*w.weight0+matrices[w.boneIndex1].MultiplyPoint3x4(v)*w.weight1+matrices[w.boneIndex2].MultiplyPoint3x4(v)*w.weight2+matrices[w.boneIndex3].MultiplyPoint3x4(v)*w.weight3;normals[i]=(matrices[w.boneIndex0].MultiplyVector(n)*w.weight0+matrices[w.boneIndex1].MultiplyVector(n)*w.weight1+matrices[w.boneIndex2].MultiplyVector(n)*w.weight2+matrices[w.boneIndex3].MultiplyVector(n)*w.weight3).normalized;}
   var mesh=new Mesh();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.vertices=vs;mesh.normals=normals;mesh.uv=original.uv;mesh.subMeshCount=original.subMeshCount;for(int sub=0;sub<original.subMeshCount;sub++){var indices=original.GetTriangles(sub);var keep=new List<int>();for(int i=0;i<indices.Length;i+=3)if(Arm(weights[indices[i]],r.bones,left)&&Arm(weights[indices[i+1]],r.bones,left)&&Arm(weights[indices[i+2]],r.bones,left))keep.AddRange(new[]{indices[i],indices[i+1],indices[i+2]});mesh.SetTriangles(keep,sub);}mesh.RecalculateBounds();string path=Root+"/"+def.id+"_"+number+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved){saved.Clear(false);saved.vertices=mesh.vertices;saved.normals=mesh.normals;saved.uv=mesh.uv;saved.subMeshCount=mesh.subMeshCount;for(int sub=0;sub<mesh.subMeshCount;sub++)saved.SetTriangles(mesh.GetTriangles(sub),sub);saved.RecalculateBounds();EditorUtility.SetDirty(saved);UnityEngine.Object.DestroyImmediate(mesh);mesh=saved;}else AssetDatabase.CreateAsset(mesh,path);var o=new GameObject(r.name,typeof(MeshFilter),typeof(MeshRenderer));o.layer=2;o.transform.SetParent(armRoot.transform,false);o.GetComponent<MeshFilter>().sharedMesh=mesh;o.GetComponent<MeshRenderer>().sharedMaterials=r.sharedMaterials;number++;}
  foreach(var side in left?new[]{"R","L"}:new[]{"R"}){bool right=side=="R";var wrist=bones.First(x=>x.name=="wrist."+side);var rotation=right?def.rightRotation:def.leftRotation;Vector3 forward=rotation*Vector3.forward;var end=wrist.position+forward*.024f;var start=new Vector3(right?.35f:-.5f,-.65f,-.65f);if(def.stats.reloadType=="melee")start=Quaternion.Inverse(def.hipRotation)*(new Vector3(right?.45f:-.55f,-.7f,-.3f)-new Vector3(def.hip.x,Mathf.Max(def.hip.y,-.18f),Mathf.Max(def.hip.z,.42f)));var bend=Vector3.Lerp(start,end,.65f)-forward*.12f;var vertices=new List<Vector3>();var uv=new List<Vector2>();var tris=new List<int>();int rings=9,segments=20;for(int ring=0;ring<rings;ring++){float t=ring/(rings-1f);Vector3 center=(1-t)*(1-t)*start+2*(1-t)*t*bend+t*t*end;Vector3 axis=(2*(1-t)*(bend-start)+2*t*(end-bend)).normalized;Vector3 x=Vector3.Cross(axis,Vector3.up).normalized,y=Vector3.Cross(axis,x);float radius=Mathf.Lerp(.085f,.043f,t);if(ring==rings-2)radius*=1.05f;for(int j=0;j<segments;j++){float angle=j*Mathf.PI*2/segments;vertices.Add(center+(x*Mathf.Cos(angle)+y*Mathf.Sin(angle))*radius);uv.Add(new Vector2(j/(float)segments,t));if(ring<rings-1){int a=ring*segments+j,b=ring*segments+(j+1)%segments;tris.AddRange(new[]{a,b,a+segments,b,b+segments,a+segments});}}}var mesh=new Mesh();mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();mesh.RecalculateBounds();string path=Root+"/"+def.id+"_sleeve_"+side+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved){saved.Clear(false);saved.vertices=mesh.vertices;saved.normals=mesh.normals;saved.uv=mesh.uv;saved.triangles=mesh.triangles;saved.RecalculateBounds();EditorUtility.SetDirty(saved);UnityEngine.Object.DestroyImmediate(mesh);mesh=saved;}else AssetDatabase.CreateAsset(mesh,path);var sleeve=new GameObject("Fitted sleeve "+side,typeof(MeshFilter),typeof(MeshRenderer));sleeve.layer=2;sleeve.transform.SetParent(armRoot.transform,false);sleeve.GetComponent<MeshFilter>().sharedMesh=mesh;sleeve.GetComponent<MeshRenderer>().sharedMaterial=source.GetComponentsInChildren<SkinnedMeshRenderer>().First(r=>r.name.StartsWith("SewnCuff")).sharedMaterial;}
  UnityEngine.Object.DestroyImmediate(source);PrefabUtility.SaveAsPrefabAsset(root,AssetDatabase.GetAssetPath(def.prefab));PrefabUtility.UnloadPrefabContents(root);
 }
}
